(* [comment removed for export] *)
Definition r90b_words_exit (ra sp gp tp s0 s1 a2 a3 a5 s3 s4 s7 s8 s11 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (D nD NW TE : Z) : machine_state -> Prop :=
  fun ms' => exists (t1' a0' a1' a4' s2' s5' t4' t5' : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp (Z_to_bv 64 32) t1' a3 s0 s1 a0' a1' a2 a3 a4' a5 (Z_to_bv 64 0) (Z_to_bv 64 1)
                  s2' s3 s4 s5' (Z_to_bv 64 TE) s7 s8 (Z_to_bv 64 NW) (Z_to_bv 64 (-2147483648)) s11 (Z_to_bv 64 TE) t4' t5' t6)
             F (Z_to_bv 64 r90b_re) fc None m' (seg_rom asegs)
    /\ munch [(D, D + nD)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

Lemma r90b_words : forall (n : nat) (jw : Z)
    (sp gp tp s0 s7 s8 t1 a0 a1 a4 s2 s5 t3 t4 t5 : word) F fc (m : mem) (D nD S nS wpld L NW JW T4 T0 IR WD A5 A6 S1 F32 : Z),
  Z.of_nat n = NW - jw -> 0 <= jw < NW -> NW <= 625 -> JW = jw -> T4 = T0 - 128 * wpld * jw -> A5 = 4 * wpld -> A6 = 2^64 - 4 * wpld ->
  0 <= IR < WD -> 1 <= WD <= 20000 -> (WD - 1 - IR) / 32 + 1 <= wpld ->
  1 <= wpld <= 626 -> 4 * wpld < D -> D mod 4 = 0 -> D + nD <= 2^47 -> (D + nD <= 0x7fff7000 \/ 0x10007fff8000 <= D) ->
  T0 mod 4 = 0 -> D + 128 * wpld * NW <= T0 + 4 * wpld -> T0 + 4 * wpld <= D + nD ->
  0 < S -> S mod 4 = 0 -> S + nS <= 2^47 -> L mod 4 = 0 -> S <= L -> L + 4 * NW <= S + nS ->
  0 < F32 -> F32 mod 4 = 0 -> F32 + 4 <= 2^47 -> (F32 + 4 <= D \/ D + nD <= F32) -> (F32 + 4 <= 0x7fff7000 \/ 0x10007fff8000 <= F32) ->
  0 <= S1 -> S1 mod 8 = 0 -> S1 + 112 <= 2^47 -> (S1 + 112 <= D \/ D + nD <= S1 + 88) ->
  rw_cells asegs m F32 [C4 (Z_to_bv 64 WD)] ->
  rw_cells asegs m (S1 + 88) [C8 (Z_to_bv 64 0)] -> rw_cells asegs m (S1 + 96) [C8 (Z_to_bv 64 67108865)] -> rw_cells asegs m (S1 + 104) [C8 (Z_to_bv 64 (18446744073709551616 - 128 * wpld))] ->
  wr_at asegs m D nD -> acc asegs m D nD -> wr_at asegs m S nS -> acc asegs m S nS -> mem_inv asegs m ->
  evt asegs (r90b_words_exit (Z_to_bv 64 L) sp gp tp s0 (Z_to_bv 64 S1) (Z_to_bv 64 IR) (Z_to_bv 64 A6) (Z_to_bv 64 A5) (Z_to_bv 64 S) (Z_to_bv 64 F32) s7 s8
               (Z_to_bv 64 2147450880) (Z_to_bv 64 NW) F fc m D nD NW (T0 - 128 * wpld * NW))
    (MS (mkR (Z_to_bv 64 L) sp gp tp (Z_to_bv 64 32) t1 (Z_to_bv 64 A6) s0 (Z_to_bv 64 S1) a0 a1 (Z_to_bv 64 IR) (Z_to_bv 64 A6) a4 (Z_to_bv 64 A5)
             (Z_to_bv 64 0) (Z_to_bv 64 1) s2 (Z_to_bv 64 S) (Z_to_bv 64 F32) s5 (Z_to_bv 64 T4) s7 s8 (Z_to_bv 64 JW) (Z_to_bv 64 (-2147483648))
             (Z_to_bv 64 2147450880) t3 t4 t5 (Z_to_bv 64 NW))
