(* [comment removed for export] *)
Definition r90b_rem_exit (ra sp gp tp s0 s1 a2 a3 a5 s3 s4 s5 s7 s8 s11 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (D nD WS TE : Z) : machine_state -> Prop :=
  fun ms' => exists (t1' a1' a4' s2' t4' t5' : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp (Z_to_bv 64 32) t1' a3 s0 s1 (Z_to_bv 64 WS) a1' a2 a3 a4' a5 (Z_to_bv 64 0) (Z_to_bv 64 1)
                  s2' s3 s4 s5 (Z_to_bv 64 TE) s7 s8 (Z_to_bv 64 WS) (Z_to_bv 64 (-2147483648)) s11 (Z_to_bv 64 TE) t4' t5' t6)
             F (Z_to_bv 64 r90b_nx) fc None m' (seg_rom asegs)
    /\ munch [(D, D + nD)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

Lemma r90b_rem : forall (n : nat) (j : Z)
    (sp gp tp s0 s1 s5 s8 t6 t1 a0 a1 a4 s2 t4 t5 : word) F fc (m : mem) (D nD S nS wpld L NW WS J T4 T0 IR WD A5 A6 F32 : Z),
  Z.of_nat n = WS - j -> 32 * NW <= j < WS -> WS < 32 * NW + 32 -> 0 <= NW -> J = j -> T4 = T0 - 4 * wpld * (j - 32 * NW) ->
  A5 = 4 * wpld -> A6 = 2^64 - 4 * wpld ->
  0 <= IR < WD -> 1 <= WD <= 20000 -> (WD - 1 - IR) / 32 + 1 <= wpld -> 1 <= WS <= 20000 ->
  1 <= wpld <= 626 -> 4 * wpld < D -> D mod 4 = 0 -> D + nD <= 2^47 -> (D + nD <= 0x7fff7000 \/ 0x10007fff8000 <= D) ->
  T0 mod 4 = 0 -> D + 4 * wpld * (WS - 1 - 32 * NW) <= T0 -> T0 + 4 * wpld <= D + nD ->
  0 < S -> S mod 4 = 0 -> S + nS <= 2^47 -> L mod 4 = 0 -> S <= L -> L + 4 * NW + 4 <= S + nS ->
  0 < F32 -> F32 mod 4 = 0 -> F32 + 20 <= 2^47 -> (F32 + 20 <= D \/ D + nD <= F32) -> (F32 + 20 <= 0x7fff7000 \/ 0x10007fff8000 <= F32) ->
  rw_cells asegs m F32 [C4 (Z_to_bv 64 WD)] -> rw_cells asegs m (F32 + 16) [C4 (Z_to_bv 64 WS)] ->
  wr_at asegs m D nD -> acc asegs m D nD -> wr_at asegs m S nS -> acc asegs m S nS -> mem_inv asegs m ->
  evt asegs (r90b_rem_exit (Z_to_bv 64 L) sp gp tp s0 s1 (Z_to_bv 64 IR) (Z_to_bv 64 A6) (Z_to_bv 64 A5) (Z_to_bv 64 S) (Z_to_bv 64 F32) s5 (Z_to_bv 64 (F32 + 16)) s8
               (Z_to_bv 64 2147450880) t6 F fc m D nD WS (T0 - 4 * wpld * (WS - 32 * NW)))
    (MS (mkR (Z_to_bv 64 L) sp gp tp (Z_to_bv 64 32) t1 (Z_to_bv 64 A6) s0 s1 a0 a1 (Z_to_bv 64 IR) (Z_to_bv 64 A6) a4 (Z_to_bv 64 A5) (Z_to_bv 64 0) (Z_to_bv 64 1)
             s2 (Z_to_bv 64 S) (Z_to_bv 64 F32) s5 (Z_to_bv 64 T4) (Z_to_bv 64 (F32 + 16)) s8 (Z_to_bv 64 J) (Z_to_bv 64 (-2147483648)) (Z_to_bv 64 2147450880)
             (Z_to_bv 64 T4) t4 t5 t6)
